(function () {
  "use strict";

  // ---- Imagens embutidas ------------------------------------------------------
  var BG_SRC = "data:image/png;base64,";
  var PHONE_SVG = '<svg viewBox="0 0 11.57 16.53" xmlns="http://www.w3.org/2000/svg"><path fill="#fff" d="M2.45 16.53 9.12 16.53C10.47 16.53 11.57 15.43 11.57 14.08L11.57 2.45C11.57 1.1 10.47 0 9.12 0L2.45 0C1.1 0 0 1.1 0 2.45L0 14.08C0 15.43 1.1 16.53 2.45 16.53ZM9.12 15.4 2.45 15.4C1.72 15.4 1.13 14.81 1.13 14.08L1.13 4.76C1.13 4.76 10.44 4.76 10.44 4.76L10.44 14.08C10.44 14.81 9.85 15.4 9.12 15.4ZM2.45 1.13 9.12 1.13C9.85 1.13 10.44 1.72 10.44 2.45L10.44 3.63 1.13 3.63 1.13 2.45C1.13 1.72 1.72 1.13 2.45 1.13Z"/><path fill="#fff" d="M5.94 13.78C5.69 13.78 5.49 13.98 5.49 14.23 5.49 14.48 5.69 14.68 5.94 14.68 6.19 14.68 6.39 14.48 6.39 14.23 6.39 13.98 6.19 13.78 5.94 13.78Z"/><path fill="#fff" d="M5.94 2.93C6.19 2.93 6.39 2.73 6.39 2.48 6.39 2.23 6.19 2.03 5.94 2.03 5.69 2.03 5.49 2.23 5.49 2.48 5.49 2.73 5.69 2.93 5.94 2.93Z"/></svg>';
  var INSTA_SVG = '<svg viewBox="0 0 35.38 35.38" xmlns="http://www.w3.org/2000/svg"><path fill="#fff" d="M27.06 6.32C25.91 6.32 24.99 7.25 24.99 8.39 24.99 9.53 25.92 10.46 27.06 10.46 28.2 10.46 29.13 9.53 29.13 8.39 29.13 7.25 28.2 6.32 27.06 6.32Z"/><path fill="#fff" d="M17.84 8.98C13.04 8.98 9.13 12.89 9.13 17.69 9.13 22.49 13.04 26.4 17.84 26.4 22.64 26.4 26.55 22.49 26.55 17.69 26.55 12.89 22.64 8.98 17.84 8.98ZM17.84 23.27C14.76 23.27 12.26 20.77 12.26 17.69 12.26 14.61 14.76 12.11 17.84 12.11 20.92 12.11 23.42 14.61 23.42 17.69 23.42 20.77 20.92 23.27 17.84 23.27Z"/><path fill="#fff" d="M24.75 35.38 10.63 35.38C4.77 35.38 0 30.61 0 24.75L0 10.63C0 4.77 4.77 0 10.63 0L24.76 0C30.62 0 35.39 4.77 35.39 10.63L35.39 24.76C35.39 30.62 30.62 35.39 24.76 35.39ZM10.63 3.33C6.61 3.33 3.33 6.6 3.33 10.63L3.33 24.76C3.33 28.78 6.6 32.06 10.63 32.06L24.76 32.06C28.78 32.06 32.06 28.79 32.06 24.76L32.06 10.63C32.06 6.61 28.79 3.33 24.76 3.33L10.63 3.33Z"/></svg>';

  function svgImage(svg) {
    var img = new Image();
    img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
    return img;
  }
  function loaded(img) {
    return new Promise(function (res) {
      if (img.complete && img.naturalWidth) return res(img);
      img.onload = function () { res(img); };
      img.onerror = function () { res(img); };
    });
  }
  var bg = new Image(); bg.src = BG_SRC;
  var phoneIcon = svgImage(PHONE_SVG);
  var instaIcon = svgImage(INSTA_SVG);

  // ---- Medidas do slide original (EMU -> px) ------------------------------------
  var W = 1200, H = 300, SLIDE_W = 6477000;
  function E(emu) { return emu * W / SLIDE_W; }
  var PT = E(12700); // 1 pt em px

  var FOOTER = "Rua San José, 485 - Pq Ind. San José II   |   CEP 06742-116  |   lpl.com.br  |  + 55 11 2238 5454   |            lplofficial";

  // Calibri (a fonte da assinatura atual). Se o computador não tiver, entra a Carlito embutida, de mesma medida.
  var CAL = '"Calibri", "CarlitoEmb", Carlito, Arial, sans-serif';
  var FONT_BOLD = '700 {s}px ' + CAL;
  var FONT_REG = '400 {s}px ' + CAL;
  var FONT_FOOT = '400 {s}px "Calibri Light", "Calibri", "CarlitoEmb", Carlito, Arial, sans-serif';
  function F(tpl, px) { return tpl.replace("{s}", px.toFixed(2)); }

  // ---- Desenho de texto -----------------------------------------------------------
  // O PowerPoint desenha o texto um pouco mais grosso que o canvas; um contorno fino compensa.
  function paint(ctx, text, x, y, lw) {
    ctx.fillText(text, x, y);
    if (lw > 0) { ctx.lineWidth = lw; ctx.lineJoin = "round"; ctx.strokeStyle = "#fff"; ctx.strokeText(text, x, y); }
  }
  function drawSpaced(ctx, text, x, y, spacing, lw) {
    for (var i = 0; i < text.length; i++) {
      paint(ctx, text[i], x, y, lw);
      x += ctx.measureText(text[i]).width + spacing;
    }
  }
  function fitFont(ctx, tpl, basePx, text, maxW) {
    var px = basePx;
    ctx.font = F(tpl, px);
    var w = ctx.measureText(text).width;
    if (w > maxW) { px = basePx * maxW / w; ctx.font = F(tpl, px); }
    return px;
  }

  // ---- Dados ----------------------------------------------------------------------------
  var el = {
    nome: document.getElementById("nome"),
    sobrenome: document.getElementById("sobrenome"),
    setor: document.getElementById("setor"),
    tel: document.getElementById("telefone"),
    hint: document.getElementById("telHint"),
    status: document.getElementById("status"),
    cv: document.getElementById("cv"),
    dl: document.getElementById("btnDownload"),
    cp: document.getElementById("btnCopy")
  };

  function formatPhone(raw) {
    var d = raw.replace(/\D/g, "").slice(0, 11);
    if (d.length <= 2) return d;
    if (d.length <= 6) return d.slice(0, 2) + " " + d.slice(2);
    if (d.length <= 10) return d.slice(0, 2) + " " + d.slice(2, 6) + " " + d.slice(6);
    return d.slice(0, 2) + " " + d.slice(2, 7) + " " + d.slice(7);
  }
  function clean(s) { return s.replace(/\s+/g, " ").trim(); }

  function values() {
    var nome = clean(el.nome.value), sob = clean(el.sobrenome.value);
    return {
      nome: nome, sobrenome: sob,
      full: clean(nome + " " + sob).toUpperCase(),
      setor: clean(el.setor.value),
      tel: el.tel.value,
      digits: el.tel.value.replace(/\D/g, "")
    };
  }
  function isValid(v) {
    return v.nome && v.sobrenome && v.setor && (v.digits.length === 10 || v.digits.length === 11);
  }

  // ---- Desenho da assinatura --------------------------------------------------------------
  var ctx = el.cv.getContext("2d");

  function render() {
    var v = values();
    var name  = v.full  || "NOME SOBRENOME";
    var setor = v.setor || "Setor";
    var tel   = v.tel   || "11 90000 0000";

    ctx.clearRect(0, 0, W, H);
    ctx.drawImage(bg, 0, 0, W, H);
    ctx.textBaseline = "alphabetic";
    ctx.fillStyle = "#fff";

    // Linhas de base medidas na assinatura atual (escala 1200x300)
    var NAME_BASE = 105.4, SETOR_BASE = 136.0, TEL_BASE = 192.1;
    var LW_NAME = 0.1, LW_SETOR = 0, LW_TEL = 0.25, LW_FOOT = 0.2;

    // Nome e setor: centralizados na caixa do slide
    var cx = E(3343416 + 2635787 / 2);
    var maxW = E(2635787) + 90;
    ctx.globalAlpha = v.full ? 1 : 0.45;
    ctx.textAlign = "center";
    fitFont(ctx, FONT_BOLD, 16 * PT, name, maxW);
    paint(ctx, name, cx, NAME_BASE, LW_NAME);

    ctx.globalAlpha = v.setor ? 1 : 0.45;
    fitFont(ctx, FONT_REG, 10 * PT, setor, maxW);
    paint(ctx, setor, cx, SETOR_BASE, LW_SETOR);

    // Telefone
    ctx.globalAlpha = v.tel ? 1 : 0.45;
    ctx.textAlign = "left";
    ctx.font = F(FONT_REG, 12 * PT);
    drawSpaced(ctx, tel, E(4169668 + 91440), TEL_BASE, 0.65 * PT, LW_TEL);
    ctx.globalAlpha = 1;

    // Ícone do telefone (girado 180°, como no original)
    var ix = E(4046500), iy = E(909137), iw = E(123168), ih = E(174487);
    ctx.save();
    ctx.translate(ix + iw / 2, iy + ih / 2);
    ctx.rotate(Math.PI);
    ctx.drawImage(phoneIcon, -iw / 2, -ih / 2, iw, ih);
    ctx.restore();

    // Rodapé (igual para todos)
    ctx.textBaseline = "middle";
    ctx.font = F(FONT_FOOT, 10.5 * PT);
    paint(ctx, FOOTER, E(127669 + 91440), E(1357640 + 45720) + 6.4 * PT, LW_FOOT);
    ctx.drawImage(instaIcon, E(5497158), E(1378615), E(182251), E(186774));
  }

  function refresh() {
    render();
    var v = values(), ok = isValid(v);
    el.dl.disabled = !ok;
    el.cp.disabled = !ok;
    var bad = el.tel.value && v.digits.length < 10;
    el.hint.textContent = bad ? "Faltam dígitos: informe DDD + número." : "DDD + número. A formatação é automática.";
    el.hint.classList.toggle("err", !!bad);
    el.status.textContent = "";
  }

  // ---- Eventos ---------------------------------------------------------------------------------
  el.tel.addEventListener("input", function () { el.tel.value = formatPhone(el.tel.value); refresh(); });
  ["nome", "sobrenome", "setor"].forEach(function (k) { el[k].addEventListener("input", refresh); });

  function slug(s) {
    return s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  }
  function toBlob() { return new Promise(function (res) { el.cv.toBlob(res, "image/png"); }); }

  el.dl.addEventListener("click", function () {
    var v = values();
    if (!isValid(v)) return;
    toBlob().then(function (blob) {
      var a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "assinatura-" + slug(v.nome + " " + v.sobrenome) + ".png";
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(function () { URL.revokeObjectURL(a.href); }, 2000);
      el.status.textContent = "Baixado: " + a.download;
    });
  });

  el.cp.addEventListener("click", function () {
    if (!isValid(values())) return;
    if (!(navigator.clipboard && window.ClipboardItem)) {
      el.status.textContent = "Este navegador não permite copiar a imagem. Use Baixar PNG.";
      return;
    }
    navigator.clipboard.write([new ClipboardItem({ "image/png": toBlob() })]).then(
      function () { el.status.textContent = "Imagem copiada. Cole no editor de assinatura do Outlook."; },
      function () { el.status.textContent = "Não foi possível copiar. Use Baixar PNG."; }
    );
  });

  // ---- Início: espera imagens e fontes antes do primeiro desenho --------------------------------
  var fontsReady = document.fonts && document.fonts.load
    ? Promise.all([document.fonts.load('400 20px "CarlitoEmb"'), document.fonts.load('700 20px "CarlitoEmb"')]).catch(function () {})
    : Promise.resolve();
  Promise.all([loaded(bg), loaded(phoneIcon), loaded(instaIcon), fontsReady]).then(refresh);
})();
